 25→///
 26→/// let content = r#"
 27→/// # Database config
 28→/// DATABASE_URL=postgres://localhost/db
 29→/// DEBUG="true"
 30→/// EMPTY=
 31→/// "#;
 32→///
 33→/// let vars = EnvFileParser::parse(content).unwrap();
 34→/// assert_eq!(vars.get("DATABASE_URL"), Some(&"postgres://localhost/db".to_string()));
 35→/// assert_eq!(vars.get("DEBUG"), Some(&"true".to_string()));
 36→/// assert_eq!(vars.get("EMPTY"), Some(&"".to_string()));
 37→/// ```
 38→pub struct EnvFileParser;
 39→
 40→impl EnvFileParser {
 41→    /// Parse an env file content string into a map of variables.
 42→    pub fn parse(content: &str) -> Result<HashMap<String, String>> {
 43→        let mut vars = HashMap::new();
 44→
 45→        for line in content.lines() {
 46→            let line = line.trim();
 47→
 48→            // Skip empty lines and comments
 49→            if line.is_empty() || line.starts_with('#') {
 50→                continue;
 51→            }
 52→
 53→            // Parse KEY=value
 54→            if let Some((key, value)) = Self::parse_line(line) {
 55→                vars.insert(key, value);
 56→            }
 57→        }
 58→
 59→        Ok(vars)
 60→    }
 61→
 62→    /// Parse a single line.
 63→    fn parse_line(line: &str) -> Option<(String, String)> {
 64→        // Strip optional `export` prefix
 65→        let line = line
 66→            .strip_prefix("export ")
 67→            .or_else(|| line.strip_prefix("export\t"))
 68→            .unwrap_or(line);
 69→
 70→        let eq_pos = line.find('=')?;
 71→        let key = line[..eq_pos].trim().to_string();
 72→        let raw_value = line[eq_pos + 1..].trim();
 73→
 74→        let value = if raw_value.starts_with('"') && raw_value.ends_with('"') && raw_value.len() >= 2
 75→        {
 76→            // Double-quoted: strip quotes and process escape sequences
 77→            Self::unescape_double_quoted(&raw_value[1..raw_value.len() - 1])
 78→        } else if raw_value.starts_with('\'') && raw_value.ends_with('\'') && raw_value.len() >= 2
 79→        {
 80→            // Single-quoted: strip quotes, no escape processing
 81→            raw_value[1..raw_value.len() - 1].to_string()
 82→        } else {
 83→            // Unquoted: strip inline comments
 84→            Self::strip_inline_comment(raw_value)
 85→        };
 86→
 87→        Some((key, value))
 88→    }
 89→
 90→    /// Process escape sequences in a double-quoted value (after outer quotes
 91→    /// have been removed).
 92→    fn unescape_double_quoted(value: &str) -> String {
 93→        let mut result = String::with_capacity(value.len());
 94→        let mut chars = value.chars();
 95→        while let Some(ch) = chars.next() {
 96→            if ch == '\\' {
 97→                match chars.next() {
 98→                    Some('n') => result.push('\n'),
 99→                    Some('t') => result.push('\t'),
100→                    Some('\\') => result.push('\\'),
101→                    Some('"') => result.push('"'),
102→                    Some('$') => result.push('$'),
103→                    Some(other) => {
104→                        result.push('\\');
105→                        result.push(other);
106→                    }
107→                    None => result.push('\\'),
108→                }
109→            } else {
110→                result.push(ch);
111→            }
112→        }
113→        result
114→    }
115→
116→    /// Strip an inline comment (`# ...`) from an unquoted value.
117→    fn strip_inline_comment(value: &str) -> String {
118→        if let Some(pos) = value.find(" #") {
119→            value[..pos].trim_end().to_string()
120→        } else {
121→            value.to_string()
122→        }
123→    }
124→
125→    /// Load and parse an env file from a path.
126→    ///
127→    /// # Example
128→    ///
129→    /// ```no_run
