131→    /// use std::path::Path;
132→    ///
133→    /// let vars = EnvFileParser::load(Path::new(".env")).unwrap();
134→    /// for (key, value) in &vars {
135→    ///     println!("{}={}", key, value);
136→    /// }
137→    /// ```
138→    pub fn load(path: &Path) -> Result<HashMap<String, String>> {
139→        let content = std::fs::read_to_string(path)?;
140→        Self::parse(&content)
141→    }
142→
143→    /// Load and parse an env file, returning empty map if file doesn't exist.
144→    pub fn load_optional(path: &Path) -> Result<HashMap<String, String>> {
145→        if path.exists() {
146→            Self::load(path)
147→        } else {
